export function estimateFor(v){const e=shippingEstimates.variants[v.id];if(!e||e.product_id!==v.product_id||e.sku!==v.sku||(v.sale_units_per_pack??1)!==e.sale_units_per_pack||(v.supplier_price_units??1)!==e.supplier_price_units||String(v.supplier_variant_id||'')!==e.supplier_variant_id||String(v.supplier_url||'').replace(/\/$/,'')!==e.supplier_url)return null;return e;}
export function shippingFill(v){const e=estimateFor(v);if(!e||v.shipping_verified)return null;const dimensionsMissing=v.dimensions_mm==null&&e.dimensions_mm!=null,weightMissing=v.weight_g==null;if(!dimensionsMissing&&!weightMissing)return null;return {...v,dimensions_mm:dimensionsMissing?[...e.dimensions_mm]:v.dimensions_mm,weight_g:weightMissing?e.weight_g:v.weight_g,shipping_verified:false,price_confirmed:v.price_estimated!==true};}
